// page_01: cover — 国内电商进入存量博弈，公私域成本差达 18 倍
export function buildSlide(pptx) {
  const slide = pptx.addSlide();

  // 背景：深藏青
  slide.background = { color: "263442" };

  // 顶部装饰条：铁锈橘
  slide.addShape("rect", {
    x: 0, y: 0, w: 13.333, h: 0.18,
    fill: { color: "B44626" }, line: { color: "B44626" }
  });

  // 报告副标识
  slide.addText("2025–2026 国内电商平台流量趋势与公私域打法研究", {
    x: 0.7, y: 0.7, w: 12, h: 0.45,
    fontFace: "Microsoft YaHei", fontSize: 16, color: "B44626", bold: true
  });

  // 主标题
  slide.addText("国内电商进入存量博弈", {
    x: 0.7, y: 1.7, w: 12, h: 1.1,
    fontFace: "Microsoft YaHei", fontSize: 44, color: "FFFFFF", bold: true
  });
  slide.addText("公私域成本差达 18 倍", {
    x: 0.7, y: 2.85, w: 12, h: 1.1,
    fontFace: "Microsoft YaHei", fontSize: 44, color: "FFFFFF", bold: true
  });

  // 分割细线
  slide.addShape("rect", {
    x: 0.7, y: 4.15, w: 1.2, h: 0.04,
    fill: { color: "B44626" }, line: { color: "B44626" }
  });

  // 副标题/核心判断
  slide.addText(
    "2026 年电商经营的主命题从「在哪里买流量」切换为「如何把每一分流量支出转化为可复用的用户资产」",
    {
      x: 0.7, y: 4.4, w: 11.5, h: 1.1,
      fontFace: "Microsoft YaHei", fontSize: 18, color: "D8DCE3"
    }
  );

  // 三个关键数字
  const stats = [
    { k: "12.8 亿", v: "全网 MAU / 同比仅 +1.2%" },
    { k: "620 元", v: "公域获客成本 / 三年 +63%" },
    { k: "18 倍", v: "公私域单客获取成本差距" }
  ];
  stats.forEach((s, i) => {
    const x = 0.7 + i * 4.0;
    slide.addText(s.k, {
      x, y: 5.7, w: 3.6, h: 0.7,
      fontFace: "Microsoft YaHei", fontSize: 30, color: "B44626", bold: true
    });
    slide.addText(s.v, {
      x, y: 6.4, w: 3.6, h: 0.45,
      fontFace: "Microsoft YaHei", fontSize: 13, color: "D8DCE3"
    });
  });

  // 底部脚注
  slide.addText("数据来源：有米有数 · QuestMobile · TMO Group · 艾瑞咨询 · 凤凰网", {
    x: 0.7, y: 7.05, w: 12, h: 0.35,
    fontFace: "Microsoft YaHei", fontSize: 11, color: "8B95A1", italic: true
  });
}

// page_02: metrics_overview — 全网 MAU 见顶、CAC 三年涨 63%
export function buildSlide(pptx) {
  const slide = pptx.addSlide();
  slide.background = { color: "FFFFFF" };

  // 顶部细条
  slide.addShape("rect", {
    x: 0, y: 0, w: 13.333, h: 0.08,
    fill: { color: "B44626" }, line: { color: "B44626" }
  });

  // 标题
  slide.addText("全网 MAU 见顶、CAC 三年涨 63%", {
    x: 0.6, y: 0.35, w: 12, h: 0.55,
    fontFace: "Microsoft YaHei", fontSize: 26, color: "263442", bold: true
  });
  slide.addText("行业从增量红利切换至存量博弈——平台争抢时长与钱包份额，商家争抢经营效率与用户资产", {
    x: 0.6, y: 0.95, w: 12.2, h: 0.45,
    fontFace: "Microsoft YaHei", fontSize: 14, color: "5A6675"
  });

  // 四张卡片式数字
  const cards = [
    {
      k: "12.82 亿", t: "全网 MAU", sub: "2026/06 · 同比 +1.2%",
      desc: "移动互联网用户规模触顶，行业级流量池封顶"
    },
    {
      k: "92.6%", t: "短视频渗透率", sub: "2026 Q2",
      desc: "用户时长高度集中于内容平台，电商竞争转向时长与复购"
    },
    {
      k: "620 元", t: "公域获客成本", sub: "2026 Q1 / 较 2023 年 +63%",
      desc: "三年涨幅超 63%，美妆食品等头部新消费品牌突破 900 元"
    },
    {
      k: "-12.5%", t: "电商从业者数量", sub: "2025/06 同比",
      desc: "平台活跃商家同步下降，存量压力已传导至供给侧"
    }
  ];

  cards.forEach((c, i) => {
    const col = i % 2;
    const row = Math.floor(i / 2);
    const x = 0.6 + col * 6.2;
    const y = 1.7 + row * 2.55;

    // 卡片底框（浅灰）
    slide.addShape("rect", {
      x, y, w: 5.9, h: 2.25,
      fill: { color: "F4F5F7" }, line: { color: "E2E5EA", width: 0.75 }
    });
    // 左侧铁锈橘竖条
    slide.addShape("rect", {
      x, y, w: 0.1, h: 2.25,
      fill: { color: "B44626" }, line: { color: "B44626" }
    });

    slide.addText(c.k, {
      x: x + 0.3, y: y + 0.18, w: 3.0, h: 0.7,
      fontFace: "Microsoft YaHei", fontSize: 30, color: "B44626", bold: true
    });
    slide.addText(c.t, {
      x: x + 0.3, y: y + 0.92, w: 5.3, h: 0.4,
      fontFace: "Microsoft YaHei", fontSize: 14, color: "263442", bold: true
    });
    slide.addText(c.sub, {
      x: x + 0.3, y: y + 1.28, w: 5.3, h: 0.35,
      fontFace: "Microsoft YaHei", fontSize: 11, color: "8B95A1", italic: true
    });
    slide.addText(c.desc, {
      x: x + 0.3, y: y + 1.65, w: 5.4, h: 0.55,
      fontFace: "Microsoft YaHei", fontSize: 11, color: "5A6675"
    });
  });

  // 底部结语
  slide.addText(
    "结论：单次流量采购 ROI 持续走低，必须把每一次公域曝光都转化为可重复触达的用户资产",
    {
      x: 0.6, y: 6.95, w: 12.2, h: 0.4,
      fontFace: "Microsoft YaHei", fontSize: 13, color: "263442", bold: true
    }
  );
}

// page_03: content — 平台格局：淘宝抖音领跑，视频号成最大变量
export function buildSlide(pptx) {
  const slide = pptx.addSlide();
  slide.background = { color: "FFFFFF" };

  slide.addShape("rect", {
    x: 0, y: 0, w: 13.333, h: 0.08,
    fill: { color: "B44626" }, line: { color: "B44626" }
  });

  slide.addText("平台格局：淘宝抖音领跑，视频号成最大变量", {
    x: 0.6, y: 0.35, w: 12, h: 0.55,
    fontFace: "Microsoft YaHei", fontSize: 26, color: "263442", bold: true
  });
  slide.addText("六大平台分层明显，视频号以 8 亿 DAU 切入商业化，年增速 45% 逼近抖音", {
    x: 0.6, y: 0.95, w: 12.2, h: 0.45,
    fontFace: "Microsoft YaHei", fontSize: 14, color: "5A6675"
  });

  // 表头
  const headers = ["平台", "用户规模", "同比增速", "角色定位"];
  const colX = [0.6, 3.0, 5.8, 8.4];
  const colW = [2.3, 2.7, 2.5, 4.4];

  slide.addShape("rect", {
    x: 0.6, y: 1.7, w: 12.2, h: 0.55,
    fill: { color: "263442" }, line: { color: "263442" }
  });
  headers.forEach((h, i) => {
    slide.addText(h, {
      x: colX[i] + 0.15, y: 1.75, w: colW[i] - 0.2, h: 0.45,
      fontFace: "Microsoft YaHei", fontSize: 13, color: "FFFFFF", bold: true
    });
  });

  // 数据行
  const rows = [
    { p: "淘宝",     u: "MAU 10 亿+",   g: "+3.7%",   r: "综合电商龙头 / 货架场",     hl: false },
    { p: "抖音",     u: "MAU 9.48 亿",  g: "+14.4%",  r: "内容电商第一 / 增速并列首位", hl: true },
    { p: "拼多多",   u: "MAU 7.08 亿",  g: "+0.9%",   r: "下沉与白牌 / 用户时长 -12%",  hl: false },
