// deck.js — 汇总 11 页 PPT
import { buildSlide as p01 } from "./pages/page_01.js";
import { buildSlide as p02 } from "./pages/page_02.js";
import { buildSlide as p03 } from "./pages/page_03.js";
import { buildSlide as p04 } from "./pages/page_04.js";
import { buildSlide as p05 } from "./pages/page_05.js";
import { buildSlide as p06 } from "./pages/page_06.js";
import { buildSlide as p07 } from "./pages/page_07.js";
import { buildSlide as p08 } from "./pages/page_08.js";
import { buildSlide as p09 } from "./pages/page_09.js";
import { buildSlide as p10 } from "./pages/page_10.js";
import { buildSlide as p11 } from "./pages/page_11.js";

export const slideBuilders = [
  p01, p02, p03, p04, p05, p06, p07, p08, p09, p10, p11
];

// deck.mjs — 入口：汇总 11 页并写出 deck.pptx
import pptxgenjs from "pptxgenjs";
import { slideBuilders } from "./deck.js";

const pptx = new pptxgenjs();
pptx.layout = "LAYOUT_WIDE"; // 13.333 × 7.5 英寸
pptx.title = "国内电商平台流量趋势与公私域打法研究报告";
pptx.author = "Reports Factory";

slideBuilders.forEach((build, idx) => {
  build(pptx);
  // 页码脚注由 buildSlide 自管
});

await pptx.writeFile({ fileName: "deck/deck.pptx" });
console.log("[deck] wrote deck/deck.pptx with", slideBuilders.length, "slides");

